// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 x, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));

        // Fund the game so a winning payout of 2 ether is possible.
        vm.deal(address(c), 5 ether);
        uint256 bankBefore = address(c).balance;

        // Target block for the guess; after jumping far past it, blockhash(target) is 0,
        // so the correct answer is deterministically keccak256(abi.encodePacked(bytes32(0))).
        vm.roll(block.number + 1);
        uint256 target = block.number;
        bytes32 answer = keccak256(abi.encodePacked(blockhash(target)));

        // The fuzzer decides whether the locked hash is the correct answer or an arbitrary one.
        bytes32 h = (x % 2 == 0) ? answer : bytes32(x);
        bool shouldPay = (h == answer);

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        // Move well beyond the 256-block window so blockhash(target) is 0 for everyone.
        vm.roll(target + 300);

        vm.prank(actor);
        c.settle();

        // General rule: the contract pays out 2 ether iff the stored guess equals the answer.
        assertTrue(
            (address(c).balance == bankBefore - 2 ether) == shouldPay,
            "payout must occur exactly when the stored guess matches the answer"
        );
    }
}

