// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }

    function testFuzz_property(uint256 startBlock, uint256 seed, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        startBlock = bound(startBlock, 1, type(uint64).max - 400);

        // target block is block.number + 1 at lock time; roll far past it so blockhash(target) == 0
        vm.roll(startBlock);
        // the deterministic answer for a target block whose blockhash is 0
        bytes32 answer = keccak256(abi.encodePacked(bytes32(0)));
        // fuzzer picks which hash is locked in: either the correct answer or an arbitrary seed
        bytes32 h = (seed % 2 == 0) ? answer : bytes32(seed);

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);

        vm.roll(startBlock + 300); // target block now >= 256 blocks old -> blockhash == 0
        vm.prank(actor);
        c.settle();

        // General rule: whenever the locked guess equals the answer, settling must pay out
        // the 2-ether prize, so the contract balance must drop from 2 ether to 0.
        // Reference: pays out (balance 0). Mutant: guess was never stored (stays bytes32(0)),
        // never equals the non-zero answer, so no payout and balance stays 2 ether.
        bool correct = (h == answer);
        assertTrue(!correct || address(c).balance == 0);
    }
}

