pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }
    function testFuzz_property(address a1, address a2, uint256 delta) public {
        vm.assume(a1 != address(0) && a2 != address(0) && a1 != a2);
        delta = bound(delta, 1, 100);
        vm.roll(block.number + delta);

        // target block is block.number+1, i.e. a future block -> blockhash is 0
        bytes32 answer = keccak256(abi.encodePacked(blockhash(block.number + 1)));

        vm.deal(a1, 1 ether);
        vm.prank(a1);
        c.lockInGuess{value: 1 ether}(answer);
        vm.deal(a2, 1 ether);
        vm.prank(a2);
        c.lockInGuess{value: 1 ether}(answer);

        uint256 before = address(c).balance; // 3 ether
        vm.roll(block.number + 300);

        vm.prank(a1);
        c.settle();

        assertTrue(address(c).balance == before - 2 ether);
    }
}

