pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 1 ether}(); }
    function testFuzz_property(address actor, bytes32 h) public {
        vm.assume(actor != address(0));
        vm.assume(h != bytes32(0));
        vm.deal(actor, 2 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(h);
        (uint blk, bytes32 stored) = c.guesses(actor);
        assertTrue(blk != 0 && stored == h);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function lockInGuess(bytes32 hash, uint256 amt) public {
        require(address(this).balance >= amt);
        (bool ok, ) = address(c).call{value: amt}(
            abi.encodeWithSignature("lockInGuess(bytes32)", hash)
        );
        bool expectedOk = (amt == 1 ether);
        assert(ok == expectedOk);
    }

    receive() external payable {}
    fallback() external payable {}
}

