contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint balBefore = address(c).balance;
        bool reverted;
        try c.lockInGuess{value: amount}(keccak256(abi.encodePacked(uint(1)))) { reverted = false; } catch { reverted = true; }
        assert(reverted || address(c).balance == balBefore + 1 ether);
    }
    receive() external payable {}
}

